#!/usr/bin/env python3
"""Actual SnartyWireless controller against recording Android service adapters.
Runs real background HTTP transfer to bridge supplied by wireless_sync_test.py.
Does not emulate the Y1 Wi-Fi chipset, Android binder or radio timing.
"""
from pathlib import Path
import os,subprocess,sys,tempfile
repo=Path(__file__).resolve().parents[3];work=Path(tempfile.mkdtemp(prefix='snarty-wifi-controller-'))
stubs={
'android/content/Context.java':'''package android.content;public class Context{public static final String WIFI_SERVICE="wifi",CONNECTIVITY_SERVICE="network";public static final int MODE_PRIVATE=0;public Context getApplicationContext(){return this;}public Object getSystemService(String s){return null;}public SharedPreferences getSharedPreferences(String s,int m){return null;}public void registerReceiver(BroadcastReceiver r,IntentFilter f){}public void unregisterReceiver(BroadcastReceiver r){}}''',
'android/content/SharedPreferences.java':'''package android.content;public interface SharedPreferences{String getString(String k,String d);boolean getBoolean(String k,boolean d);long getLong(String k,long d);Editor edit();interface Editor{Editor putString(String k,String v);Editor putBoolean(String k,boolean v);Editor putLong(String k,long v);boolean commit();}}''',
'android/content/BroadcastReceiver.java':'package android.content;public abstract class BroadcastReceiver{public abstract void onReceive(Context c,Intent i);}',
'android/content/Intent.java':'package android.content;public class Intent{public Object extra;public Object getParcelableExtra(String key){return extra;}}',
'android/content/IntentFilter.java':'package android.content;public class IntentFilter{public IntentFilter(String a){}public void addAction(String a){}}',
'android/os/Looper.java':'package android.os;public class Looper{public static Looper getMainLooper(){return new Looper();}}',
'android/os/Handler.java':'''package android.os;public class Handler{public static Runnable next;public Handler(Looper l){}public void post(Runnable r){next=r;}public void postDelayed(Runnable r,long d){next=r;}public void removeCallbacks(Runnable r){if(next==r)next=null;}public static void runOne(){Runnable r=next;next=null;if(r!=null)r.run();}}''',
'android/os/Environment.java':'package android.os;import java.io.*;public class Environment{public static File root;public static File getExternalStorageDirectory(){return root;}}',
'android/os/SystemClock.java':'package android.os;public class SystemClock{public static long now=2000000;public static long elapsedRealtime(){return now;}}',
'android/net/NetworkInfo.java':'package android.net;public class NetworkInfo{public boolean connected;public boolean isConnected(){return connected;}}',
'android/net/ConnectivityManager.java':'package android.net;public class ConnectivityManager{public static final int TYPE_WIFI=1;public NetworkInfo info=new NetworkInfo();public NetworkInfo getNetworkInfo(int t){return info;}}',
'android/net/wifi/WifiInfo.java':'package android.net.wifi;public class WifiInfo{public String getSSID(){return "Test Home";}}',
'android/net/wifi/ScanResult.java':'package android.net.wifi;public class ScanResult{public String SSID,capabilities;public int level;public ScanResult(String s,String c){SSID=s;capabilities=c;level=-50;}}',
'android/net/wifi/WifiConfiguration.java':'package android.net.wifi;import java.util.*;public class WifiConfiguration{public String SSID,preSharedKey;public boolean hiddenSSID;public int networkId;public BitSet allowedKeyManagement=new BitSet();public static class KeyMgmt{public static final int NONE=0,WPA_PSK=1;}}',
'android/net/wifi/WifiManager.java':'''package android.net.wifi;import java.util.*;public class WifiManager{public static final String NETWORK_STATE_CHANGED_ACTION="net",WIFI_STATE_CHANGED_ACTION="wifi",EXTRA_NETWORK_INFO="info";public static final int WIFI_MODE_FULL_HIGH_PERF=3;public boolean enabled;public int locks,releases;public WifiConfiguration configured;public List<ScanResult> scans=new ArrayList<ScanResult>();public boolean isWifiEnabled(){return enabled;}public boolean setWifiEnabled(boolean b){enabled=b;return true;}public WifiInfo getConnectionInfo(){return new WifiInfo();}public boolean startScan(){return enabled;}public List<ScanResult> getScanResults(){return new ArrayList<ScanResult>(scans);}public List<WifiConfiguration> getConfiguredNetworks(){return new ArrayList<WifiConfiguration>();}public int updateNetwork(WifiConfiguration c){configured=c;return 1;}public int addNetwork(WifiConfiguration c){configured=c;return 1;}public boolean enableNetwork(int n,boolean b){return true;}public boolean saveConfiguration(){return true;}public boolean reconnect(){return true;}public class WifiLock{boolean held;public void acquire(){held=true;locks++;}public boolean isHeld(){return held;}public void release(){held=false;releases++;}}public WifiLock createWifiLock(int m,String s){return new WifiLock();}}''',
'org/rockbox/ArtistImages.java':'package org.rockbox;import java.io.*;public class ArtistImages{public static int starts;public static void start(File f){starts++;}}',
'org/rockbox/RockboxService.java':'''package org.rockbox;import android.content.*;import android.net.*;import android.net.wifi.*;import java.util.*;public class RockboxService extends Context{public WifiManager wifi=new WifiManager();public ConnectivityManager network=new ConnectivityManager();public boolean mounted=true,running=false;public BroadcastReceiver receiver;public P prefs=new P();public Object getSystemService(String s){return s.equals(WIFI_SERVICE)?wifi:network;}public SharedPreferences getSharedPreferences(String s,int m){return prefs;}public boolean mediaStorageReady(){return mounted;}public boolean isRockboxRunning(){return running;}public void registerReceiver(BroadcastReceiver r,IntentFilter f){receiver=r;}public void unregisterReceiver(BroadcastReceiver r){receiver=null;}public static class P implements SharedPreferences,SharedPreferences.Editor{Map<String,Object> m=new HashMap<String,Object>();public String getString(String k,String d){return m.containsKey(k)?(String)m.get(k):d;}public boolean getBoolean(String k,boolean d){return m.containsKey(k)?(Boolean)m.get(k):d;}public long getLong(String k,long d){return m.containsKey(k)?(Long)m.get(k):d;}public SharedPreferences.Editor edit(){return this;}public SharedPreferences.Editor putString(String k,String v){m.put(k,v);return this;}public SharedPreferences.Editor putBoolean(String k,boolean v){m.put(k,v);return this;}public SharedPreferences.Editor putLong(String k,long v){m.put(k,v);return this;}public boolean commit(){return true;}}}''',
'org/rockbox/WirelessControllerTest.java':'''package org.rockbox;import java.io.*;import java.nio.file.*;import android.os.*;import android.content.*;import android.net.*;import android.net.wifi.*;public class WirelessControllerTest{static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static String cmd(SnartyWireless w,int n,String s)throws Exception{return new String(w.command(n,s==null?null:s.getBytes("UTF-8")),"UTF-8");}static void done(SnartyWireless w,int locks)throws Exception{long deadline=System.currentTimeMillis()+12000;while(System.currentTimeMillis()<deadline){if(cmd(w,1,null).startsWith("Sync complete")&&RockboxServiceForTest.wifi.releases>=locks)return;Thread.sleep(20);}throw new AssertionError(cmd(w,1,null));}static RockboxService RockboxServiceForTest;public static void main(String[]a)throws Exception{Environment.root=Files.createTempDirectory("wifi-controller-drive-").toFile();RockboxService s=new RockboxService();RockboxServiceForTest=s;SnartyWireless w=new SnartyWireless(s);w.start();check(cmd(w,0,null).contains("off"),"off status");check(cmd(w,2,null).contains("Enabling"),"enable");s.wifi.scans.add(new ScanResult("Enterprise","[WPA2-EAP]"));check(cmd(w,6,"Enterprise\\tabcdefgh").contains("WPA2-Personal"),"enterprise rejection");check(cmd(w,6,"Home\\tshort").contains("8-63"),"short password");String name="Home\\\"\\\\WiFi";String password="abcdefgh\\\"";check(cmd(w,6,name+"\\t"+password).contains("Connecting"),"connect");check(s.wifi.configured.SSID.contains("\\\\\\\""),"quoted SSID");check(s.wifi.configured.preSharedKey.contains("\\\\\\\""),"quoted PSK");cmd(w,6,"Free\\t");check(s.wifi.configured.allowedKeyManagement.get(WifiConfiguration.KeyMgmt.NONE),"open network");check(cmd(w,9,"http://1.1.1.1:8787\\t"+a[1]).contains("private"),"public endpoint rejected");File pairing=new File(Environment.root,".rockbox/snarty/wireless-pairing.json");pairing.getParentFile().mkdirs();String json="{\\\"version\\\":1,\\\"url\\\":\\\""+a[0]+"\\\",\\\"key\\\":\\\""+a[1]+"\\\"}";Files.write(pairing.toPath(),json.getBytes("UTF-8"));check(cmd(w,12,null).contains("Paired"),"pairing import");check(!pairing.exists(),"pairing secret removed from card");s.network.info.connected=true;Handler.runOne();Thread.sleep(80);check(s.wifi.locks==0,"no sync before core initialized");s.running=true;Handler.runOne();done(w,1);check(new File(Environment.root,"Music/A/song.mp3").isFile(),"automatic real transfer");check(s.wifi.locks==1&&s.wifi.releases==1,"bounded transfer Wi-Fi lock");check(cmd(w,11,null).equals("changed")&&cmd(w,11,null).isEmpty(),"core changed event once");check(!cmd(w,10,null).contains(a[1]),"status excludes key");Handler.runOne();Thread.sleep(50);check(s.wifi.locks==1,"no repeated sync inside interval");Intent loss=new Intent();NetworkInfo lost=new NetworkInfo();loss.extra=lost;s.receiver.onReceive(s,loss);Handler.runOne();done(w,2);check(s.wifi.locks==2,"quick disconnect/reconnect triggers sync");cmd(w,8,null);s.receiver.onReceive(s,loss);Handler.runOne();Thread.sleep(80);check(s.wifi.locks==2,"automatic sync off honored");cmd(w,3,null);check(!s.wifi.enabled,"disable radio");w.stop();check(s.receiver==null,"receiver cleanup");System.out.println("PASS: actual Android controller with recording adapters: Wi-Fi controls/WPA2 quoting/open/EAP validation, private pairing import, deferred startup, automatic transfer, reconnect/debounce, auto toggle, bounded Wi-Fi lock, one-shot library refresh and receiver cleanup");}}'''}
# Java fixture strings deliberately use escaped tabs/newlines above; normalize
# those Java source escapes, not any credentials passed in arguments.
for n,s in stubs.items():
    if n.endswith('WirelessControllerTest.java'):s=s.replace('\\\\t','\\t')
    p=work/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
jar=Path(os.environ.get('SNARTY_JSON_JAR','/workspace/setup/wireless-tests/json.jar'))
subprocess.run(['javac','-cp',str(jar),'-d',str(work),*[str(work/n) for n in stubs],*[str(repo/'android/y1/src/org/rockbox'/n) for n in ('SnartyWireless.java','WirelessSync.java','WirelessProtocol.java')]],check=True)
subprocess.run(['java','-cp',str(work)+os.pathsep+str(jar),'org.rockbox.WirelessControllerTest',sys.argv[1],sys.argv[2]],check=True)
